import { UnknownReferenceError } from "./errors.js";

/**
 * @typedef {object} Customer
 * @property {string} customerId
 * @property {string} name
 * @property {string} country
 */

/** Customers by id, for lookups. */
export function buildCustomerIndex(records) {
  const index = new Map();
  for (const record of records) {
    index.set(record.customerId, record);
  }
  return index;
}

/** The customer with this id; `referencedBy` names the record that asked for it, for the error message. */
export function requireCustomer(index, id, referencedBy) {
  const customer = index.get(id);
  if (!customer) {
    throw new UnknownReferenceError("customer", id, referencedBy);
  }
  return customer;
}
import { readFileSync } from "node:fs";
import { join } from "node:path";

function readJson(directory, file) {
  return JSON.parse(readFileSync(join(directory, file), "utf8"));
}

export function loadInvoices(directory) {
  return readJson(directory, "invoices.json");
}

/** The customers of both systems in one list: billing first, then the CRM. */
export function loadCustomerRecords(directory) {
  return [
    ...readJson(directory, "billing-customers.json"),
    ...readJson(directory, "crm-customers.json"),
  ];
}
/** A record refers to something that does not exist, for example an invoice to an unknown customer. */
export class UnknownReferenceError extends Error {
  constructor(kind, id, referencedBy) {
    const origin = referencedBy ? ` (referenced by ${referencedBy})` : "";
    super(`Unknown ${kind} "${id}"${origin}`);
    this.name = "UnknownReferenceError";
    this.kind = kind;
    this.id = id;
  }
}
